 require_once(__DIR__.'/../init.php'); common_notices::registerNoticeClasses([ 'common_notices', 'crm_passworddb_notices', 'med_ambulance_notices', 'med_reception_notices', ]); class common_notices { const NOTICE_LONG_REQUEST_SLEEP = 2; const NOTICE_LONG_REQUEST_TIMEOUT = 10 * 60; const NOTICE_CLOSE_TIMEOUT = 5 * 60; const NOTICE_TEMPLATES = [ 'system-close-notice' => [ 'persist' => false ] ]; private static array $noticeTemplates; public static function createNotice(object $notice): bool { if (!($redis = Cache::getInstance())) { return false; } $noticeKey = self::getNoticeKey($notice); if ($redis->exists($noticeKey)) { $notice->parentId = $noticeKey; } $redis->multi(Redis::PIPELINE); self::createNoticeInternal($notice); $redis->exec(); return true; } public static function deleteNotice(object $notice): bool { if (!($redis = Cache::getInstance())) { return false; } $noticeKey = self::getNoticeKey($notice); $noticeRaw = $redis->get($noticeKey); if ($noticeRaw !== false) { $notice = self::unserialize($noticeRaw); $redis->multi(Redis::PIPELINE); self::deleteNoticeInternal($notice, true); $redis->exec(); return true; } return false; } public static function waitNotices(object $params): object|false { if (!($redis = Cache::getInstance())) { return false; } $enterpriseCode = getSessionValue('mapEnterpriseCode', 0); $userCode = getSessionValue('mapUserCode', getSessionValue('user')); $task = getSessionValue('app'); if (!isset($enterpriseCode, $userCode, $task)) { return false; } $allowTypes = static::findNoticeTypes($task, $foundUserTypes); if (!$foundUserTypes) { return false; } $databaseId = getDatabaseId(); $timeKeys = [ "nc:$databaseId:time:u:$userCode", "nc:$databaseId:time:e:$enterpriseCode", "nc:$databaseId:time" ]; $lastWaitUTime = (float)isEmptyProperty($params, 'lastId', 0); $requestEndUTime = time() + self::NOTICE_LONG_REQUEST_TIMEOUT; do { self::callCheckMethods($allowTypes); $now = new DateTime(); $nowUTime = (float)$now->format('U.u'); $resultNotices = []; $redis->multi(Redis::PIPELINE); for ($iTime = 0; $iTime < count($timeKeys); $iTime++) { $redis->zRangeByScore($timeKeys[$iTime], $lastWaitUTime ?: '-inf', $nowUTime); } $noticeKeys = $redis->exec(); $redis->multi(Redis::PIPELINE); for ($iTime = 0; $iTime < count($timeKeys); $iTime++) { if (!empty($noticeKeys[$iTime])) { $redis->mGet($noticeKeys[$iTime]); } } $notices = $redis->exec(); $redis->multi(Redis::PIPELINE); $iNotice = 0; for ($iTime = 0; $iTime < count($timeKeys); $iTime++) { if (empty($noticeKeys[$iTime])) { continue; } foreach ($noticeKeys[$iTime] as $iKey => $noticeKey) { $noticeRaw = $notices[$iNotice][$iKey]; if ($noticeRaw === false) { continue; } $notice = self::unserialize($noticeRaw); if ($notice->validTime < $now) { self::deleteNoticeInternal($notice, true); } else if (isset($allowTypes[$notice->type]) && ($template = self::getTemplate($notice->type))) { if (isset($template['isNecessaryCheck']) && !self::{$template['isNecessaryCheck']}($notice)) { self::deleteNoticeInternal($notice, true); } else if (empty($notice->processed[$userCode])) { $notice->id = $noticeKey; mergeObjects($notice, (object)$template); unset($notice->class, $notice->checkMethod, $notice->isNecessaryCheck); $resultNotices[] = $notice; } } } $iNotice++; } $redis->exec(); $lastWaitUTime = $nowUTime; if (!empty($resultNotices)) { return (object)[ 'lastId' => $lastWaitUTime, 'notices' => $resultNotices ]; } sleep(self::NOTICE_LONG_REQUEST_SLEEP); } while (time() < $requestEndUTime); return (object)['lastId' => $lastWaitUTime]; } public function confirmNotice(string $id): bool { return self::updateNotice($id, true); } public function cancelNotice(string $id): bool { return self::updateNotice($id, false); } private function updateNotice(string $id, bool $isConfirm): bool { if (!($redis = Cache::getInstance())) { return false; } $noticeRaw = $redis->get($id); if ($noticeRaw !== false) { $notice = self::unserialize($noticeRaw); $redis->multi(Redis::PIPELINE); if (isset($notice->userCode)) { self::deleteNoticeInternal($notice, false); } else if (!empty($notice->singleton) && $isConfirm) { self::deleteNoticeInternal($notice, true); } else { $notice->processed[getSessionValue('mapUserCode', getSessionValue('user'))] = 1; $redis->set($id, self::serialize($notice)); } $redis->exec(); return true; } return false; } protected static function filterNoticeTypes(array &$types) { } private static function findNoticeTypes(string $task, ?bool &$foundUserTypes): array { $types = []; $foundUserTypes = false; foreach (self::$noticeTemplates as $type => $template) { $tasks = $template['tasks'] ?? null; if (empty($tasks) || (ctype_punct($tasks[0]) && preg_match($tasks, $task) === 1) || (ctype_alpha($tasks[0]) && in_array($task, safe_explode(',', $tasks))) ) { if (!empty($tasks)) { $foundUserTypes = true; } $types[$type] = 1; } } static::filterNoticeTypes($types); return $types; } private static function callCheckMethods(array $types): void { foreach ($types as $type) { $template = self::getTemplate($type); if (isset($template['checkMethod'])) { $template['class']::{$template['checkMethod']}(); } } } private static function getTemplate(string $type): ?array { return self::$noticeTemplates[$type] ?? null; } private static function getNoticeKey(object $notice): string { $databaseId = getDatabaseId(); return "nc:$databaseId:$notice->type:$notice->source"; } private static function getTimeKey(object $notice): string { $databaseId = getDatabaseId(); $timeKey = "nc:$databaseId:time"; if (isset($notice->userCode)) { $timeKey .= ":u:$notice->userCode"; } else if (isset($notice->enterpriseCode)) { $timeKey .= ":e:$notice->enterpriseCode"; } return $timeKey; } private static function createNoticeInternal(object $notice): void { $redis = Cache::getInstance(); $noticeKey = self::getNoticeKey($notice); $timeKey = self::getTimeKey($notice); $notice->id = $noticeKey; $notice->noticeTime = $notice->noticeTime ?? new DateTime(); $notice->userCodeAuthor = $params->userCodeAuthor ?? getSessionValue('mapUserCode', getSessionValue('user')); $validSeconds = max($notice->validTime->getTimestamp() - $notice->noticeTime->getTimestamp(), 1); $redis->set($noticeKey, self::serialize($notice), ['ex' => $validSeconds]); $redis->zAdd($timeKey, (float)$notice->noticeTime->format('U.u'), $noticeKey); } private static function deleteNoticeInternal(object $notice, bool $isCreateCloseNotice): void { $redis = Cache::getInstance(); $noticeKey = self::getNoticeKey($notice); $timeKey = self::getTimeKey($notice); $redis->unlink($noticeKey); $redis->zRem($timeKey, $noticeKey); if ($isCreateCloseNotice && $notice->type !== 'system-close-notice') { $notice->type = 'system-close-notice'; $notice->source = $noticeKey; $notice->parentId = $noticeKey; $notice->userCodeAuthor = getSessionValue('mapUserCode', getSessionValue('user')); $notice->processed[$notice->userCodeAuthor] = 1; $notice->noticeTime = new DateTime(); try { $timeoutClose = self::NOTICE_CLOSE_TIMEOUT; $notice->validTime = (new DateTime())->modify("+ $timeoutClose seconds"); } catch (Exception) { return; } unset($notice->user, $notice->data); self::createNoticeInternal($notice); } } private static function serialize(object $notice): string { $notice->noticeTime = dbDateTime($noticeTime = $notice->noticeTime); $notice->validTime = dbDateTime($validTime = $notice->validTime); $result = igbinary_serialize($notice); $notice->noticeTime = $noticeTime; $notice->validTime = $validTime; return $result; } private static function unserialize(string $notice): object { $result = igbinary_unserialize($notice); try { $result->noticeTime = new DateTime($result->noticeTime); } catch (Exception) { $result->noticeTime =new DateTime(); } try { $result->validTime = new DateTime($result->validTime); } catch (Exception) { $result->validTime =new DateTime(); } return $result; } public static function registerNoticeClasses(array $classes): void { foreach ($classes as $class) { foreach ($class::NOTICE_TEMPLATES as $type => $newTemplate) { if (($template = self::getTemplate($type))) { throw new ErrorException("Уведомление \"$class.$type\" уже зарегистрировано в классе \"{$template['class']}\""); } $newTemplate['class'] = $class; self::$noticeTemplates[$type] = $newTemplate; } } } } handleJsonRpc('common_notices'); 